function prepareAutoService(){const c=currentCustomer(),condition=state.customerConditions[c.id],budget=effectiveBudget(c,condition),candidates=availableServices(),matched=candidates.filter(service=>service.matches.includes(c.concern)||condition?.targets?.some(target=>service.matches.includes(target))),affordable=(matched.length?matched:candidates).filter(service=>service.price<=budget),service=(affordable.length?affordable:matched.length?matched:candidates).sort((a,b)=>b.base-a.base)[0],plans=createTreatmentPlans(service,c,state,state.staff);state.session.choice={response:`${state.staff.name}が丁寧にご案内します。`,trust:0,satisfaction:Math.round(state.staff.service/30),face:'normal',beforeTrust:c.trust};state.session.selectedService=service.id;state.session.selectedPlan=plans.sort((a,b)=>b.score-a.score)[0];state.session.treatmentBonus=0;state.session.autoMode=true;state.session.phase='treatment'}
