function ownerPortrait(expression='smile',size='lg',options={}){const appearance=options.preview===false?getOwnerAppearance():displayedOwnerAppearance();return officialPortrait('owner','owner',state.player.name,size,'',expression).replace('portrait-owner',`portrait-owner owner-official-fixed owner-appearance-avatar${options.home?' owner-home-avatar':''}`).replace('<figure ',`<figure data-owner-hair="${appearance.hairStyle}" data-owner-color="${appearance.hairColor}" data-owner-makeup="${appearance.makeup}" data-owner-outfit="${appearance.dress||appearance.tops||''}" `)}
function beautyVisualFor(record){const fallback=createBeautyVisualProfile(record?.serviceId||'relax',Number(record?.score||0));return{treatment:record?.beforeVisual?.effect?.replace('before-','')||fallback.treatment,tier:record?.resultTier||fallback.tier,intensity:Number(record?.visualIntensity??fallback.intensity),before:record?.beforeVisual||fallback.before,after:record?.afterVisual||fallback.after,type:record?.type||fallback.type}}
function beautyPortrait(c,record,phase='before',size='md'){const visual=beautyVisualFor(record),profile=phase==='after'?visual.after:visual.before,expression=profile.expression||(phase==='after'?record?.afterExpression:record?.beforeExpression)||'normal';return`<div class="beauty-visual beauty-${phase} treatment-${visual.treatment} result-${visual.tier}" style="--beauty-intensity:${visual.intensity}" data-beauty-phase="${phase}" data-treatment="${visual.treatment}" data-result-tier="${visual.tier}">${customerPortrait(c,expression,size)}${phase==='after'?'<span class="beauty-sparkles" aria-hidden="true">✦ ♡ ✦</span>':''}</div>`}
function applyFashionPreview(itemId){const item=fashionItems.find(x=>x.id===itemId);if(!item)return false;state.ui.previewAppearance=previewFashionAppearance(getOwnerAppearance(),item);state.ui.previewItemId=item.id;state.ui.previewContext={type:'fashion',itemId:item.id};return true}
function applyBeautyPreview(kind,value){const current=displayedOwnerAppearance(),next={...current};if(kind==='hairStyle')next.hairStyle=value;if(kind==='hairColor')next.hairColor=ownerHairColorValue(value);if(kind==='makeup')next.makeup=value;state.ui.previewAppearance=next;state.ui.previewItemId=null;state.ui.previewContext={type:'beauty'};return next}
function cancelAppearancePreview(){state.ui.previewAppearance=null;state.ui.previewItemId=null;state.ui.previewContext=null;return getOwnerAppearance()}
function commitAppearancePreview(){const appearance=state.ui.previewAppearance;if(!appearance)return false;let cost=0;const fashionId=state.ui.previewContext?.itemId,fashionItem=fashionItems.find(x=>x.id===fashionId);if(fashionItem&&!state.wardrobe.owned.includes(fashionId))cost+=fashionItem.price;if(!state.wardrobe.hairOwned.includes(appearance.hairStyle)){const index=hairstyles20.indexOf(appearance.hairStyle);cost+=Math.max(0,5000+index*500)}const makeup=makeupStyles.find(x=>x.id===appearance.makeup);if(makeup&&!state.wardrobe.makeupOwned.includes(makeup.id))cost+=makeup.price;if(state.money<cost){notify('所持金が足りません');return false}state.money-=cost;if(fashionItem&&!state.wardrobe.owned.includes(fashionId)){state.wardrobe.owned.push(fashionId);state.brandAffinity[fashionItem.brand]=Math.min(100,state.brandAffinity[fashionItem.brand]+10);state.news.unshift(`${fashionItem.brand}で「${fashionItem.name}」を購入しました`)}if(!state.wardrobe.hairOwned.includes(appearance.hairStyle))state.wardrobe.hairOwned.push(appearance.hairStyle);if(makeup&&!state.wardrobe.makeupOwned.includes(makeup.id))state.wardrobe.makeupOwned.push(makeup.id);appearanceToLegacy(state,appearance);cancelAppearancePreview();save();return true}
function townPageV5(){const positions={salon:[50,60],fashionShop:[76,27],beautyShop:[24,27],cafe:[76,72],school:[24,72]},selected=positions[state.town.lastVisit],target=selected?[selected[0]+(selected[0]>50?-8:8),Math.min(87,selected[1]+12)]:[50,82];return`<div class="section-title"><h2>TOWN</h2><span class="pill">サロンの外へ出かけよう</span></div><div class="town-map v5-town" data-asset-slot="assets/town/">${optionalArt('./assets/town/town-main.webp?v=61','town-background-art','美容タウン')}<div class="town-player" style="left:${target[0]}%;top:${target[1]}%">${ownerPortrait('smile','sm')}</div>${townBuildings.map((x,i)=>{const p=positions[x.id];return`<button class="town-map-point ${i>0?'has-news':''}" data-town="${x.id}" style="--point-x:${p[0]}%;--point-y:${p[1]}%"><span class="map-point-icon" aria-hidden="true">${x.icon}</span><b>${x.name}</b></button>`}).join('')}</div><p class="town-help">施設名をタップして移動できます。</p>`}
function staffPageV5(){if(!state.staff)return`<div class="section-title"><h2>一緒に働くスタッフを選ぶ</h2><span class="pill">それぞれ得意分野が違います</span></div><div class="staff-roster">${staffOptions.map(s=>`<div class="card">${staffPortrait({...s,role:'新人'},'smile','lg')}<h3>${s.name}</h3><span class="pill">${s.trait}</span>${ability(s)}<p>月給 ${yen(s.salary)}</p><button class="primary wide" data-hire="${s.id}">採用する</button></div>`).join('')}</div>`;const p=staffProfile(),next=roles[roles.indexOf(state.staff.role)+1],need=promotionNeeds[next];return`<div class="section-title"><h2>スタッフプロフィール</h2><span class="pill">${state.staff.role} · Lv.${state.staff.level}</span></div><div class="staff-profile card character-panel">${staffPortrait(state.staff,state.staff.bond>=60?'happy':'smile','lg')}<div><h1>${state.staff.name}</h1><p>${p.age}歳・${p.personality}</p><div class="bond"><span>♡ 仲良し度</span><strong>${state.staff.bond}/100</strong><div class="bar"><i style="width:${state.staff.bond}%"></i></div></div><div class="row"><span>Energy</span><b>${state.staff.energy}%</b></div><div class="row"><span>人気・指名</span><b>${state.staff.popularity}・${state.staff.nominations}回</b></div></div></div><div class="grid"><div class="card"><h3>プロフィール</h3><div class="row"><span>好き</span><b>${p.likes}</b></div><div class="row"><span>夢</span><b>${p.dream}</b></div><div class="row"><span>得意</span><b>${p.best}</b></div><div class="row"><span>苦手</span><b>${p.weak}</b></div></div><div class="card"><h3>能力・実績</h3>${ability(state.staff)}<div class="row"><span>売上</span><b>${yen(state.staff.monthlySales)}</b></div><div class="row"><span>PERFECT</span><b>${state.staff.monthlyPerfect}回</b></div></div><div class="card"><h3>昇格</h3>${next?`<p>次の役職：<b>${next}</b></p>${Object.entries(need).map(([k,v])=>`<div class="row"><span>${{level:'Lv.',bond:'仲良し度',treatments:'施術人数',service:'接客'}[k]}</span><b>${state.staff[k]||0} / ${v}</b></div>`).join('')}<button class="primary wide" data-action="promote" ${canPromote()?'':'disabled'}>${next}へ昇格</button>`:'<div class="goal-complete">🏆 店長資格を取得済み</div>'}</div><div class="card"><h3>習得スキル</h3>${state.staff.skills.length?state.staff.skills.map(x=>`<span class="skill-chip">${x}</span>`).join(''):'<p>Training Schoolで習得できます</p>'}</div><div class="card"><h3>広告</h3>${adsHTML()}</div></div>`}
