function fashionItemCardV5(x){const appearance=getOwnerAppearance(),key={dresses:'dress',bags:'bag'}[x.category]||x.category,owned=state.wardrobe.owned.includes(x.id),equipped=appearance[key]===x.id,preview=state.ui.previewItemId===x.id,rarity=x.price>=30000?'PREMIUM':x.price>=16000?'RARE':'NORMAL';return`<div class="card fashion-item ${equipped?'equipped':''} ${preview?'previewing':''}"><button class="fashion-thumb" data-try-fashion="${x.id}" aria-label="${x.name}を試着">${x.icon}</button><div class="fashion-meta"><span class="brand-tag brand-${x.brand}">${x.brand}</span><span class="rarity-badge">${rarity}</span></div><h3>${x.name}</h3><p>STYLE：${brands[x.brand].label} +${x.points}</p><small>${equipped?'装備中':owned?'所持済み':yen(x.price)}</small><button class="${preview?'primary':'soft'} wide" data-try-fashion="${x.id}">${preview?'試着中':equipped?'別コーデを試す':'試着する'}</button></div>`}
function beautyShopPageV5(){const tab=state.ui.beautyTab||'hair',appearance=displayedOwnerAppearance();return`<button class="soft" data-nav="town">← 街へ戻る</button><div class="shop-banner beauty-banner"><span>💄</span><div><small>HAIR & MAKEUP</small><h1>Beauty Shop</h1><p>選んだ瞬間、オーナーの見た目が変わります</p></div></div><div class="beauty-preview v61-beauty-preview">${tryOnPanel('Beautyプレビュー')}<section><div class="beauty-tabs"><button data-beauty-tab="hair" class="${tab==='hair'?'active':''}">HAIR</button><button data-beauty-tab="color" class="${tab==='color'?'active':''}">COLOR</button><button data-beauty-tab="makeup" class="${tab==='makeup'?'active':''}">MAKEUP</button></div>${tab==='hair'?`<div class="option-grid v61-beauty-options">${hairstyles20.map((x,i)=>{const owned=state.wardrobe.hairOwned.includes(x);return`<button data-preview-hair="${x}" class="beauty-option ${appearance.hairStyle===x?'selected':''}"><span>${i%4===0?'✂️':i%4===1?'🎀':i%4===2?'✨':'🌸'}</span><b>${x}</b><small>${owned?'所持済み':yen(5000+i*500)}</small></button>`}).join('')}</div>`:tab==='color'?`<div class="option-grid v61-color-options">${ownerHairColors.map((x,i)=>`<button data-preview-color="${x}" class="beauty-option ${appearance.hairColor===x?'selected':''}"><span class="hair-swatch swatch-${i%6}">●</span><b>${x}</b><small>プレビュー</small></button>`).join('')}</div>`:`<div class="grid v61-makeup-options">${makeupStyles.map(x=>{const owned=state.wardrobe.makeupOwned.includes(x.id);return`<button class="card beauty-makeup ${appearance.makeup===x.id?'equipped':''}" data-preview-makeup="${x.id}"><div class="item-icon">${x.icon}</div><h3>${x.name}</h3><p>${x.style} +${x.points}</p><small>${owned?'所持済み':yen(x.price)}</small></button>`}).join('')}</div>`}</section></div>`}
function ownerPageV5(){const style=styleScores(),equipped=Object.entries(state.wardrobe.equipped).filter(([,v])=>v).map(([,id])=>fashionItems.find(x=>x.id===id)?.name).filter(Boolean);return`<div class="section-title"><h2>サロンオーナー</h2><span class="pill">Energy ${state.ownerEnergy}%</span></div><div class="card owner-editor character-panel">${ownerPortrait('smile','lg')}<div><label>あなたの名前<input id="player-name" value="${state.player.name}" maxlength="12"></label>${selectHTML('skin','肌色',skinColors,state.player.skin)}${selectHTML('hairStyle','髪型',hairstyles20,state.player.hairStyle)}${selectHTML('hairColor','髪色',hairColors,state.player.hairColor)}<button class="primary wide" data-action="savePlayer">アバターを保存</button></div></div><div class="card style-board"><h2>STYLE</h2>${Object.entries(style).map(([k,v])=>`<div><span>${{feminine:'フェミニン',luxury:'高級感',trend:'トレンド',natural:'ナチュラル'}[k]}</span><b>${v}</b><div class="bar"><i style="width:${Math.min(100,v)}%"></i></div></div>`).join('')}<p>着用中：${equipped.join('・')||'旧衣装プリセット'}／メイク：${makeupStyles.find(x=>x.id===state.wardrobe.makeup)?.name}</p></div><div class="quick-links"><button class="quick-link" data-nav="fashionShop"><b>👗</b>着せ替え</button><button class="quick-link" data-nav="beautyShop"><b>💄</b>ヘア・メイク</button></div>`}
function customersPageV5(){const met=state.encounteredCustomers.length,total=state.customers.length,pct=Math.round(met/total*100);return`<div class="collection-head"><span>CUSTOMER COLLECTION</span><strong>${met} / ${total} · ${pct}%</strong><div class="bar"><i style="width:${pct}%"></i></div></div><div class="grid">${state.customers.map(c=>state.encounteredCustomers.includes(c.id)?`<div class="card chart-card customer-portrait-card ${customerRank(c)==='VIP'?'vip':''}"><div class="chart-head">${customerPortrait(c,c.trust>=90?'joy':c.trust>=70?'happy':'normal','sm')}<div><h3>${c.name} <small>${c.age}歳</small></h3><span class="rank rank-${customerRank(c)}">${customerRank(c)}</span></div></div><p>${c.job}・${c.category}</p><div class="row"><span>お悩み</span><b>${c.concern}</b></div><div class="row"><span>信頼度</span><b>${c.trust}</b></div><button class="soft wide" data-chart="${c.id}">カルテを見る</button></div>`:`<div class="card mystery-card"><div class="silhouette portrait-placeholder">👤</div><h3>？？？</h3><p>年齢不明・職業不明</p><small>${state.unlockedCustomers.includes(c.id)?'もうすぐ出会えるかも…':unlockHint(c.unlockCondition)}</small></div>`).join('')}</div>`}
function customerChartV5(){const c=state.customers.find(x=>x.id===state.selectedCustomer);if(!c||!state.encounteredCustomers.includes(c.id))return customersPageV5();const story=nextCustomerStory(c),progress=state.customerStories[c.id]||0,rank=customerRank(c);return`<button class="soft" data-nav="customers">← 一覧へ</button><div class="card full-chart"><div class="character-panel ${rank==='VIP'?'vip':''}">${customerPortrait(c,c.trust>=90?'joy':c.trust>=60?'happy':'normal','lg')}<div><h1>${c.name} <small>${c.age}歳</small></h1><span class="rank rank-${rank}">${rank}</span>${rank==='VIP'?'<span class="vip-badge">✦ VIP</span>':''}<p>${c.job}・${c.category}</p><div class="trust-meter"><b>信頼度 ${c.trust}</b><div class="bar"><i style="width:${c.trust}%"></i></div></div></div></div>${customerStoryIds.includes(c.id)?`<div class="story-progress"><b>CHARACTER STORY ${progress}/5</b><div class="bar"><i style="width:${progress/5*100}%"></i></div>${story?`<button class="primary wide" data-story="${c.id}">STORY「${story.title}」を見る</button>`:'<small>信頼度や来店回数を増やすと続きが解禁されます</small>'}</div>`:''}<div class="chart-grid">${[['職業',c.job],['性格',c.personality],['悩み',c.concern],['予算',yen(c.budget)],['趣味',c.hobby],['好きな美容',c.beautyFavorite],['苦手な接客',c.dislikes],['来店回数',`${c.visits}回`],['累計利用額',yen(c.totalSpent)],['紹介人数',`${c.referrals||0}人`],['お気に入り施術',c.favoriteService||'—'],['お気に入りスタッフ',c.favoriteStaff||'—']].map(([a,b])=>`<div><span>${a}</span><b>${b}</b></div>`).join('')}</div><h3>来店履歴</h3>${c.visitHistory?.length?c.visitHistory.slice(-5).reverse().map(v=>`<div class="review-mini"><b>Day ${v.day}</b><span>${v.service}・満足度 ${v.score}</span></div>`).join(''):'<div class="empty">まだ履歴はありません</div>'}</div>`}
function storyEventPageV5(){const c=state.customers.find(x=>x.id===state.storyEvent?.customerId),step=c&&nextCustomerStory(c);if(!c||!step)return customerChartV5();const episode=storyEpisodes[c.id]?.[step.step-1],title=episode?.[0]||step.title,text=episode?.[1]||storyText[c.id]?.[step.step-1],choices=episode?.[2]||['気持ちに寄り添う','次の目標を考える'];return`<div class="story-scene v5-story v62-story"><span class="event-label">STORY · ${c.name} Chapter ${step.step}</span>${customerPortrait(c,step.step>=3?'happy':'normal','lg')}<div class="story-dialogue"><h1>${title}</h1><div class="speech"><b>${c.name}</b><br>「${text}」</div><p>どう答える？</p><div class="choices">${choices.map((x,i)=>`<button class="choice" data-story-choice="${i}">${i?'✦':'♡'} ${x}</button>`).join('')}</div></div>${ownerPortrait('smile','sm')}</div>`}
function clientPanel(c,expression='normal',reason=''){const rank=customerRank(c),reserved=state.session?.reservationIds?.includes(c.id),condition=state.customerConditions[c.id],budget=effectiveBudget(c,condition),memory=nextVisitMemoryLine(state.customerMemory[c.id]);return`<aside class="client-profile card ${rank==='VIP'?'vip':''}">${customerPortrait(c,expression,'lg')}<h2>${c.name}様</h2><div>${rank==='VIP'?'<span class="vip-badge">VIP</span>':`<span class="rank rank-${rank}">${rank}</span>`}${reserved?'<span class="reservation-badge">予約</span>':''}</div>${condition?`<div class="condition-badge">${condition.icon} ${condition.name}</div><div class="condition-talk">「${condition.line}」</div>`:''}${memory?`<div class="v62-memory">前回の記憶<br>「${memory}」</div>`:''}<div class="row"><span>お悩み</span><b>${c.concern}</b></div><div class="row"><span>今日の予算</span><b>${yen(budget)}</b></div><div class="row"><span>信頼度</span><b>${c.trust}</b></div><div class="bar"><i style="width:${c.trust}%"></i></div>${reason?`<p class="visit-reason">${reason}</p>`:''}</aside>`}
function manualServiceRequired(){return!!state.session?.ownerForced}
function assignmentPageV6(c){const required=manualServiceRequired(c),remaining=state.session.queue.length-state.session.index;return`${salonScene('waiting',c)}<div class="v6-assignment card"><div><small>WHO WILL SERVE?</small><h2>${c.name}様を誰が担当しますか？</h2><p>${state.customerConditions[c.id]?.icon||'♡'} ${state.customerConditions[c.id]?.line||'今日もよろしくお願いします。'}</p>${required?'<span class="important-customer">✦ このストーリーはオーナー対応</span>':''}</div><div class="v6-assign-actions"><button class="primary" data-action="manualService">自分で接客する<small>信頼・ストーリー・満足度上限UP</small></button><button class="soft" data-action="autoService" ${required?'disabled':''}>${state.staff.name}に任せる<small>Energy節約・スタッフXP・指名UP</small></button></div>${remaining>1&&!required?`<button class="soft wide v6-batch" data-action="autoRemaining">残り${remaining}名をまとめてスタッフに任せる</button>`:''}<button class="soft wide" data-action="pauseTown">顧客の合間に街へ出る</button></div>`}
function treatmentDecisionPageV6(c){const event=state.session.treatmentEvent;return`${salonScene('treatment',c)}<div class="v6-treatment-event card"><span class="pill">施術中の判断</span><h2>${event.title}</h2><p>${event.text}</p><div class="v6-event-choices">${event.choices.map((choice,index)=>`<button data-treatment-choice="${index}">${choice[0]}</button>`).join('')}</div></div>`}
function businessEventPageV6(){const event=state.session.eventQueue[state.session.eventCursor];return`<div class="v6-breaking"><span>${event.icon}</span><small>BREAKING NEWS · ${event.categoryName}</small><h1>${event.title}</h1><p>${event.text}</p><div class="v6-event-choices">${event.choices.map((choice,index)=>`<button data-event-choice="${index}"><b>${'ABC'[index]}</b>${choice.label}</button>`).join('')}</div></div>`}
function businessEventResultPageV62(){const r=state.session.eventResult;return`<section class="v62-event-result ${r.positive?'positive':'caution'}"><small>EVENT RESULT</small><h1>${r.title}</h1><p>${r.message}</p><div class="speech">「${r.reaction}」</div><div class="v62-result-changes">${r.changes.length?r.changes.map(x=>`<div><span>${x.label}</span><b class="${x.value>=0?'plus':'minus'}">${x.value>=0?'+':''}${x.value}</b></div>`).join(''):'<div><span>変化</span><b>次の営業判断に反映</b></div>'}</div><button class="primary wide" data-action="continueEvent">営業へ戻る</button></section>`}
function treatmentServicePageV62(c){const reason=state.session.reasons?.[c.id]||'来店',condition=state.customerConditions[c.id]||{};return`${salonScene('counsel',c)}<div class="consult-layout v62-treatment-layout">${clientPanel(c,'normal',reason)}<section><div class="section-title"><div><small>STEP 1 / 2</small><h2>何の施術をする？</h2></div><span class="pill">悩み ${c.concern}</span></div><p>解禁済みの施術から自由に選べます。今日の状態は「${condition.name||'通常'}」です。</p><div class="v62-service-grid">${availableServices().map(service=>{const fit=treatmentAffinity(service,c,condition);return`<button class="v62-service-card ${fit.className}" data-treatment-service="${service.id}"><span>${service.icon}</span><div><h3>${service.name}</h3><b>${fit.label}</b><small>基本 ${yen(service.price)} · ${service.time}分</small></div></button>`}).join('')}</div></section></div>`}
function treatmentPlanPageV62(c){const service=availableServices().find(x=>x.id===state.session.selectedService),plans=createTreatmentPlans(service,c,state,state.staff);return`${salonScene('counsel',c)}<div class="consult-layout v62-treatment-layout">${clientPanel(c,'normal',state.session.reasons?.[c.id])}<section><div class="section-title"><div><small>STEP 2 / 2</small><h2>${service.name}のプラン</h2></div><button class="soft" data-action="backToServices">施術を選び直す</button></div><div class="v62-plan-grid">${plans.map(plan=>`<button class="v62-plan-card plan-${plan.id}" data-treatment-plan="${plan.id}"><small>${plan.id.toUpperCase()}</small><h3>${plan.name}</h3><strong>${yen(plan.price)}</strong><span>${plan.time}分</span><b>${plan.budgetLabel}</b><p>${plan.description}</p><em>${plan.risk}</em></button>`).join('')}</div></section></div>`}
function treatmentPlanReactionPageV62(c){const service=availableServices().find(x=>x.id===state.session.selectedService),plan=state.session.selectedPlan;return`${salonScene('counsel',c)}<div class="consult-layout">${clientPanel(c,plan.score>=82?'happy':'normal',state.session.reasons?.[c.id])}<section class="card proposal-reaction"><span class="pill">${service.name} · ${plan.name}</span><h2>${yen(plan.price)} · ${plan.time}分</h2><div class="speech">「${plan.reaction}」</div><p>${plan.affinity.label} ／ ${plan.budgetLabel}</p><button class="primary wide" data-action="confirmPlan">この内容で施術する</button><button class="soft wide" data-action="backToPlans">プランを選び直す</button></section></div>`}
function idleDayPageV62(){return`<section class="v62-idle-day"><small>QUIET DAY</small><h1>今日は静かな一日になりそうです</h1><p>空いた時間も、未来のサロンを育てる一日です。</p><div class="v62-idle-actions">${idleDayActions.map(x=>`<button data-idle-action="${x.id}"><b>${x.name}</b><span>${x.description}</span></button>`).join('')}</div></section>`}
function businessResumePageV62(){const s=state.session;if(!resumableSession(s))return homeV56();const done=Math.min(s.index,s.queue.length),remaining=s.queue.length-done;return`<section class="v62-resume"><span class="pill">営業中</span><h1>営業途中のデータがあります</h1><div class="card"><div class="row"><span>対応済み</span><b>${done} / ${s.queue.length}名</b></div><div class="row"><span>本日売上</span><b>${yen(state.todaySales)}</b></div><div class="row"><span>スタッフEnergy</span><b>${state.staff?.energy||0}%</b></div><div class="row"><span>残りのお客様</span><b>${remaining}名</b></div></div><button class="primary wide" data-action="resumeBusiness">営業を再開</button><button class="soft wide" data-action="closeBusinessEarly">今日は閉店する</button></section>`}
function pauseBusiness(target='town'){if(!canPauseBusiness(state.session))return notify('この場面が終わるまで移動できません');state.activeBusinessSession=copy(state.session);state.pausedBusinessState={day:state.day,screen:target,savedAt:Date.now()};state.screen=target;save();render()}
function resumeBusiness(){if(!resumableSession(state.session))return;state.screen=state.session.phase==='serviceResult'?'serviceResult':'play';save();render()}
function closeBusinessEarly(){if(!state.session)return;const remaining=state.session.queue.slice(state.session.index);state.declinedCustomers+=remaining.length;const remainingReservations=remaining.filter(id=>state.session.reservationIds?.includes(id)).length;if(remainingReservations){state.popularity=Math.max(0,state.popularity-remainingReservations*2);state.rating=clamp(state.rating-.05*remainingReservations,1,5)}state.todayHighlights.push(`途中閉店：残り${remaining.length}名`);closeDay()}
function resolveIdleDay(id){const action=idleDayActions.find(x=>x.id===id);if(!action)return;if(id==='town')return pauseBusiness('town');const e=action.effects||{};state.socialFollowers+=Number(e.followers||0);state.popularity+=Number(e.popularity||0);if(state.staff){state.staff.tech=clamp(state.staff.tech+Number(e.tech||0),0,100);state.staff.energy=clamp(state.staff.energy+Number(e.energy||0),0,100)}state.todayHighlights.push(`暇な日の行動：${action.name}`);closeDay()}
function autoSummaryPageV6(){const results=state.session.autoSummary||[];return`<div class="v6-auto-summary card"><span class="pill">STAFF REPORT</span><h1>${state.staff.name}におまかせ完了</h1>${results.map(result=>`<div class="v6-auto-row"><span>${result.customer}<small>${result.service}</small></span><b class="${result.className}">${result.label}</b><strong>+${yen(result.sales)}</strong></div>`).join('')}<button class="primary wide" data-action="continueAuto">営業を続ける</button></div>`}
function proposalStars(value){return'★'.repeat(Math.max(1,Math.min(5,Math.ceil(value/20))))+'☆'.repeat(5-Math.max(1,Math.min(5,Math.ceil(value/20))))}
function proposalServicePageV61(c){const reason=state.session.reasons?.[c.id]||'来店',choices=getTreatmentChoices(c,state,state.staff,availableServices());state.session.treatmentChoices=choices;return`${salonScene('counsel',c)}<div class="consult-layout v61-proposal-layout">${clientPanel(c,'normal',reason)}<section><div class="section-title"><div><small>TREATMENT PROPOSAL</small><h2>今日の3つのご提案</h2></div><span class="pill">担当 ${state.player.name}</span></div><p class="proposal-lead">お悩み・予算・今日の状態を見て選びましょう。最適な案は毎日変わります。</p><div class="v61-proposal-grid">${choices.map((choice,index)=>`<button class="v61-proposal-card role-${choice.role}" data-proposal="${index}"><div class="proposal-head"><b>${'ABC'[index]}</b><span>${choice.type}</span><strong>${proposalStars(choice.value)}</strong></div><h3>${choice.name}</h3><div class="proposal-price"><b>${yen(choice.price)}</b><span>${choice.time}分</span></div><div class="proposal-tags">${choice.tags.map(tag=>`<i>${tag}</i>`).join('')}</div><p>${choice.reason}</p><dl><div><dt>予算</dt><dd class="${choice.budgetFit.className}">${choice.budgetFit.label}</dd></div><div><dt>悩み</dt><dd>${choice.concernFit}</dd></div><div><dt>今日の状態</dt><dd>${choice.conditionFit}</dd></div><div><dt>トレンド</dt><dd>${choice.trendBonus?`+${choice.trendBonus}`:'—'}</dd></div><div><dt>スタッフ</dt><dd>+${choice.staffBonus}</dd></div></dl><div class="proposal-expect">期待：満足度 ${choice.satisfactionModifier>=0?'+':''}${choice.satisfactionModifier}</div><small class="proposal-risk">注意：${choice.risk}</small><em>予想反応「${choice.reaction.text}」</em></button>`).join('')}</div></section></div>`}
function proposalReactionPageV61(c){const proposal=state.session.selectedProposal;return`${salonScene('counsel',c)}<div class="consult-layout">${clientPanel(c,proposal.reaction.face,state.session.reasons?.[c.id])}<section class="card proposal-reaction"><span class="pill">${proposal.type} · ${proposal.reaction.kind}</span><h2>${proposal.name}</h2><div class="speech">「${proposal.reaction.text}」</div><div class="proposal-confirm"><span>${yen(proposal.price)} · ${proposal.time}分</span><b>満足度期待 ${proposal.satisfactionModifier>=0?'+':''}${proposal.satisfactionModifier}</b></div><button class="primary wide sticky-action" data-action="confirmProposal">この施術で進める</button><button class="soft wide" data-action="backToProposals">別の提案を見る</button></section></div>`}
function selectTreatmentProposal(index){const proposal=state.session.treatmentChoices?.[index]||getTreatmentChoices(currentCustomer(),state,state.staff,availableServices())[index];if(!proposal)return;state.session.selectedProposal=proposal;state.session.phase='proposalReaction';render()}
function confirmTreatmentProposal(){const proposal=state.session.selectedProposal;if(!proposal)return;state.session.selectedService=proposal.serviceId;state.session.eventModifiers.review+=Number(proposal.reviewModifier||0);selectService(proposal.serviceId)}
function playPageV6(){const phase=state.session.phase,c=currentCustomer();if(phase==='idleDay')return idleDayPageV62();if(phase==='assign')return assignmentPageV6(c);if(phase==='service')return treatmentServicePageV62(c);if(phase==='plan')return treatmentPlanPageV62(c);if(phase==='planReaction')return treatmentPlanReactionPageV62(c);if(phase==='treatmentDecision')return treatmentDecisionPageV6(c);if(phase==='businessEvent')return businessEventPageV6();if(phase==='businessEventResult')return businessEventResultPageV62();if(phase==='autoSummary')return autoSummaryPageV6();if(phase==='exit')return`${salonScene('exit',c)}<div class="arrival-banner">${c.name}様がお帰りになりました<small>ありがとうございました。またお待ちしています。</small></div>`;return playPageV5()}
function playPageV5(){const c=currentCustomer(),phase=state.session.phase,reason=state.session.reasons?.[c.id]||'来店',reserved=state.session.reservationIds?.includes(c.id);if(phase==='newCustomer')return`<div class="new-customer v5-new"><div>✨ NEW CUSTOMER ✨</div>${customerPortrait(c,'surprised','lg')}<h1>${c.name}</h1><p>${c.age}歳・${c.job}</p><strong>${reason}<br>新しいお客様がSalon Storyを見つけました！</strong><button class="primary wide" data-action="meetCustomer">お迎えする</button></div>`;if(phase==='arrival')return`${salonScene('arrival',c)}<div class="arrival-banner">${reserved?'📅 ご予約':'🚪 ご来店'} · ${c.name}様<small>${reason}</small></div>`;if(phase==='reaction'){const x=state.session.choice;return`${salonScene('sofa',c)}<div class="consult-layout">${clientPanel(c,x.face,reason)}<div class="card reaction-card"><h2>${c.name}様の反応</h2><div class="speech">「${x.response}」</div><div class="change-line"><span>信頼度</span><b>${x.beforeTrust} → <em>${c.trust}</em></b><strong class="${x.trust>=0?'plus':'minus'}">${x.trust>=0?'+':''}${x.trust}</strong></div><div class="change-line"><span>満足度補正</span><strong>${x.satisfaction>=0?'+':''}${x.satisfaction}</strong></div><button class="primary wide sticky-action" data-action="chooseService">施術を提案する</button></div></div>`}if(phase==='service')return`${salonScene('sofa',c)}<div class="consult-layout">${clientPanel(c,'normal',reason)}<section><div class="section-title"><h2>施術を選ぶ</h2><span class="pill">担当 ${state.staff.name}</span></div><div class="service-list">${availableServices().map(s=>{const match=s.matches.includes(c.concern),machine=machineBonus(c),trend=state.dailyTrend.targets.includes(c.concern)?state.dailyTrend.bonus:0,fashion=outfitBonus(c,s).bonus+coordinateBonus(c).bonus;return`<button class="service service-detail ${match?'':'bad'}" data-service="${s.id}"><div class="service-icon">${s.icon}</div><div><b>${s.name} Lv.${s.level}</b><div>${yen(s.price)}・${s.time}分</div><div class="service-badges">${match?'<span class="pill recommend-badge">おすすめ</span>':''}${machine?`<span class="pill">機器 +${machine}</span>`:''}${trend?`<span class="pill">トレンド +${trend}</span>`:''}</div><small class="bonus-preview">STYLE +${fashion} · 相性は施術後に判明</small></div><strong>›</strong></button>`}).join('')}</div></section></div>`;if(phase==='treatment')return`${salonScene('treatment',c)}<div class="treatment"><div>🫧　✨　💆🏻‍♀️　✨</div><h2>施術中…</h2><button class="soft" data-action="skipTreatment">スキップ</button></div>`;return`${salonScene('sofa',c)}<div class="consult-layout">${clientPanel(c,'normal',reason)}<section class="consult-copy"><div class="section-title"><h2>カウンセリング</h2><span class="pill">${state.session.index+1}/${state.session.queue.length}人目</span></div><div class="speech">「${c.dialogue}」</div><h3>どう答える？</h3><div class="choices">${c.counseling.map((x,i)=>`<button class="choice" data-counsel="${i}"><b>${'ABCD'[i]}.</b> ${x[1]}</button>`).join('')}</div></section></div>`}
function serviceResultPageV5(){const r=state.session.results.at(-1),c=state.customers.find(x=>x.name===r.customer);return`<div class="game-result-scene">${salonScene('checkout',c)}</div><div class="card result game-result ${r.className} ${r.score>=90?'perfect-burst':''}"><div class="result-label">${r.label}</div>${r.auto?`<span class="pill">${state.staff.name}のおまかせ接客</span>`:''}<div class="result-portrait">${customerPortrait(c,r.face,'lg')}</div><h2>${r.customer}様</h2>${r.condition?`<span class="condition-badge">${r.condition}</span>`:''}<div class="speech">「${r.response}」</div><div class="score" style="--score:${r.score}"><strong>${r.score}</strong></div><div class="change-line number-pop"><span>売上</span><strong class="plus">+${yen(r.sales)}</strong></div><div class="change-line number-pop"><span>信頼度</span><b>${r.trustBefore} → <em>${r.trustAfter}</em></b></div><div class="change-line number-pop"><span>店舗人気</span><strong>${r.popGain>=0?'+':''}${r.popGain}</strong></div><div class="change-line number-pop"><span>獲得XP</span><strong>+${r.xp}</strong></div><div class="change-line"><span>次回来店率</span><b>${r.repeatBefore}% → <em>${r.repeatAfter}%</em></b></div>${r.treatmentBonus?`<div class="bonus-chip">✦ 施術判断 +${r.treatmentBonus}</div>`:''}${r.fashion?`<div class="bonus-chip">🎀 STYLE +${r.fashion}</div>`:''}${r.machine?`<div class="bonus-chip">⚡ 美容機器 +${r.machine}</div>`:''}${r.trend?`<div class="bonus-chip">🔥 トレンド +${r.trend}</div>`:''}${r.affinity?`<div class="bonus-chip">♡ スタッフ相性 +${r.affinity}</div>`:''}${r.nomination?`<div class="rank-up">🌟 ${state.staff.name}を指名！ +${yen(r.nomination)}</div>`:''}${r.rankBefore!==r.rankAfter?`<div class="rank-up">🎊 顧客ランクUP！ ${r.rankAfter}</div>`:''}<button class="primary wide sticky-action" data-action="nextCustomer">${state.session.index+1<state.session.queue.length?'お見送りして次へ':'お見送りして閉店'}</button></div>`}
function serviceResultPageV62(){const r=state.session.results.at(-1),c=state.customers.find(x=>x.id===r.customerId),ba=r.beforeAfter;return`<div class="game-result-scene">${salonScene('checkout',c)}</div><section class="card result game-result v62-service-result ${r.className} ${r.score>=90?'perfect-burst':''}"><div class="result-label">${r.label}</div>${r.auto?`<span class="pill">${state.staff.name}のおまかせ接客</span>`:''}<div class="v62-before-after"><figure><small>BEFORE</small>${beautyPortrait(c,ba,'before','md')}<b class="beauty-caption">施術前</b></figure><span>✦</span><figure class="after"><small>AFTER</small>${beautyPortrait(c,ba,'after','md')}<b class="beauty-caption">${ba?.type||'美容変化'}</b></figure></div><h2>${r.customer}様</h2><span class="condition-badge">${r.service}</span><div class="speech">「${r.response}」</div><div class="score" style="--score:${r.score}"><strong>${r.score}</strong></div>${[['売上',`+${yen(r.sales)}`],['信頼度',`${r.trustBefore} → ${r.trustAfter}`],['店舗人気',`${r.popGain>=0?'+':''}${r.popGain}`],['獲得XP',`+${r.xp}`]].map(([a,b])=>`<div class="change-line number-pop"><span>${a}</span><strong>${b}</strong></div>`).join('')}<button class="primary wide sticky-action" data-action="nextCustomer">${state.session.index+1<state.session.queue.length?'お見送りして次へ':'お見送りして閉店'}</button></section>`}
function worldPageV5(){const ranked=ranking();return`<div class="section-title"><h2>SALON WORLD</h2><span class="pill">現在 ${rankingPosition()}位</span></div>${chapterCard()}<h3>人気ランキング</h3><div class="ranking">${ranked.map((r,i)=>`<div class="card rank-row ${r.self?'self':''}"><strong>${i+1}</strong><span>${r.self?'🌸':state.rivals.find(x=>x.name===r.name)?.icon} ${r.name}</span><b>${r.popularity}</b></div>`).join('')}</div>${state.rivalsUnlocked?`<h3>ライバルオーナー</h3><div class="grid">${state.rivals.map((r,i)=>{const o=rivalOwners[r.id];return`<div class="card rival-owner">${rivalPortrait(r.id,o.name,'lg')}<span class="pill">${r.name} · ${ranked.findIndex(x=>x.name===r.name)+1}位</span><h3>${o.name}</h3><p>${o.personality}／${r.type||'得意分野を研究中'}</p><div class="speech">「${o.line}」</div></div>`}).join('')}</div><div class="card contest-card"><h2>🏆 地域美容サロンAWARD</h2><p>口コミ・人気・技術・店舗Rank・接客の総合審査</p>${state.contest.lastRanking?`<div class="contest-podium">${state.contest.lastRanking.map((x,i)=>`<div class="podium ${i===0?'first':''}"><b>${i+1}${i===0?'st':'位'}</b><span>${x}</span></div>`).join('')}</div>`:''}<button class="primary" data-action="contest">コンテストに参加</button><b>${state.contest.best?`最高：${state.contest.best}`:'未参加'}</b></div>`:'<div class="card mystery-rival">🔒 Chapter 2クリアでライバルサロンが登場します</div>'}`}
function collectionSummary(){const ownedFashion=state.wardrobe.owned.length,totalFashion=fashionItems.length,ownedMachines=Object.values(state.machines).filter(x=>x?.owned).length,story=Object.values(state.customerStories).reduce((a,b)=>a+b,0),cats=[['CUSTOMER',state.encounteredCustomers.length,state.customers.length],['FASHION',ownedFashion,totalFashion],['BEAUTY',state.wardrobe.makeupOwned.length+8,makeupStyles.length+hairstyles20.length],['MACHINE',ownedMachines,machines.length],['STORE',state.stores.length,state.stores.length>1?2:2],['STORY',story,customerStoryIds.length*5],['ACHIEVEMENT',state.achievements.length,8]];return`<div class="collection-categories">${cats.map(([n,v,t])=>`<div class="collection-category"><span>${n}</span><strong>${v} / ${t}</strong><small>${Math.round(v/t*100)}%</small></div>`).join('')}</div>`}
function dataPageV5(){const h=state.history.slice(-10),max=Math.max(...h.map(x=>x.sales),1),totalGuests=h.reduce((a,x)=>a+x.guests,0),totalProfit=h.reduce((a,x)=>a+x.profit,0),branch=state.stores.find(x=>x.id!=='main');return`<div class="section-title"><h2>経営ダッシュボード</h2><span class="pill">累計 ${yen(state.cumulativeSales)}</span></div><div class="dashboard-kpis"><div class="card"><span>直近売上</span><strong>${yen(h.reduce((a,x)=>a+x.sales,0))}</strong></div><div class="card"><span>直近利益</span><strong>${yen(totalProfit)}</strong></div><div class="card"><span>来店人数</span><strong>${totalGuests}名</strong></div><div class="card"><span>口コミ</span><strong>★ ${state.rating.toFixed(1)}</strong></div></div><div class="card"><h3>日別売上</h3>${h.length?`<div class="chart">${h.map(x=>`<div style="height:${x.sales/max*100}%"><span>D${x.day}</span></div>`).join('')}</div>`:'<div class="empty">営業後に表示されます</div>'}</div><h3>店舗比較</h3><div class="compare-scroll"><table class="compare-table"><thead><tr><th>店舗</th><th>立地</th><th>店長</th><th>累計売上</th><th>人気</th><th>客層</th></tr></thead><tbody>${state.stores.map(s=>{const a=secondStoreAreas.find(x=>x.id===s.area);return`<tr><td><b>${s.name}</b></td><td>${a?.name||'本店'}</td><td>${s.manager||'オーナー'}</td><td>${yen(s.sales)}</td><td>${s.popularity}</td><td>${a?.audience||'幅広い層'}</td></tr>`}).join('')}</tbody></table></div><h3>スタッフ比較</h3>${state.staff?`<div class="compare-scroll"><table class="compare-table"><thead><tr><th>スタッフ</th><th>技術</th><th>接客</th><th>営業</th><th>速度</th><th>Energy</th><th>人気</th><th>指名</th><th>売上</th><th>PERFECT</th></tr></thead><tbody><tr><td><b>${state.staff.name}</b></td><td>${state.staff.tech}</td><td>${state.staff.service}</td><td>${state.staff.sales}</td><td>${state.staff.speed}</td><td>${state.staff.energy}%</td><td>${state.staff.popularity}</td><td>${state.staff.nominations}</td><td>${yen(state.staff.monthlySales)}</td><td>${state.staff.monthlyPerfect}</td></tr></tbody></table></div>`:'<div class="empty">スタッフ未採用</div>'}<h3>COLLECTION</h3>${collectionSummary()}<button class="soft danger" data-action="reset">セーブデータを削除</button>`}

