  document.querySelectorAll('[data-preview-makeup]').forEach(b=>b.onclick=()=>{applyBeautyPreview('makeup',b.dataset.previewMakeup);render()});
  document.querySelectorAll('[data-beauty-tab]').forEach(b=>b.onclick=()=>{state.ui.beautyTab=b.dataset.beautyTab;render()});
  document.querySelector('[data-action="cancelAppearance"]')?.addEventListener('click',()=>{cancelAppearancePreview();render()});
  document.querySelector('[data-action="commitAppearance"]')?.addEventListener('click',()=>{if(commitAppearancePreview()){notify('新しいスタイルを保存しました！');render()}});
  document.querySelector('[data-action="cancelPreview"]')?.addEventListener('click',()=>{state.ui.preview=null;render()});
  document.querySelector('[data-action="commitPreview"]')?.addEventListener('click',()=>{const p=state.ui.preview;if(!p)return;if(p.type==='fashion'){const x=fashionItems.find(y=>y.id===p.itemId);if(!state.wardrobe.owned.includes(x.id)){if(!spend(x.price))return;state.wardrobe.owned.push(x.id);state.brandAffinity[x.brand]=Math.min(100,state.brandAffinity[x.brand]+10)}Object.assign(state.wardrobe.equipped,p.equipped)}else{if(p.player?.hairStyle){const i=hairstyles20.indexOf(p.player.hairStyle),cost=i<8?0:5000+i*500;if(cost&&!spend(cost))return}if(p.makeup&&!state.wardrobe.makeupOwned.includes(p.makeup)){const m=makeupStyles.find(x=>x.id===p.makeup);if(!spend(m.price))return;state.wardrobe.makeupOwned.push(m.id)}Object.assign(state.player,p.player||{});if(p.makeup)state.wardrobe.makeup=p.makeup}state.ui.preview=null;save();notify('新しいスタイルを保存しました！')});
